import requests
import six
import logging

from base64 import b64encode
from lxml import html
from .exception import CannotEnableServices

requests.packages.urllib3.disable_warnings()


TRS_URL_TEMPLATE = 'https://{}/protected/{{}}'
CGI_DICT = {
    'login': 'login.cgi',
    'logout': 'logout.cgi',
    'enable_ssh': 'enableSsh.cgi',
    'disable_ssh': 'disableSsh.cgi',
    'disable_rnd_ports': 'disableRndPorts.cgi',
    'enable_rnd_ports': 'enableRndPorts.cgi',
    'remove_trs_configuration': 'RecoverNode.cgi'
}


def _encode_credentials(username, password):
    message = '{}:{}'.format(username, password)
    message = b64encode(bytes(message, 'utf-8') if six.PY3 else message)
    return message.decode('utf-8') if six.PY3 else message


def _create_html_string_with_hidden_items(html_document):
    """Searches HTML document for hidden items.
    :return: Request parameter string containing the hidden items.
             Returns default items if not.
    """
    hidden_items = []
    default_items = ('########', '********', '$%$%$%$%')
    for search in ('stamp', 'token', 'frame'):
        items = html_document.xpath("//input[@name='{}']/@value".format(search))
        if items:
            hidden_items.append(items[0])
        else:
            hidden_items = default_items
            break
    return '?stamp={}&token={}&frame={}'.format(*hidden_items)


class LocalRequestForwarder(object):
    """Class stores methods needed to forward http request to fsm locally using requests module.
    """
    def __init__(self, trs_ip, trs_user, trs_pass, timeout):
        """
        :param string trs_ip:    Transport IP address.
        :param string trs_user:  Transport username.
        :param string trs_pass:  Transport password.
        """
        self._trs_ip = trs_ip
        self._trs_user = trs_user
        self._trs_pass = trs_pass
        self._timeout = timeout
        self._trs_url = TRS_URL_TEMPLATE.format(trs_ip)
        self._cookies = None
        self._response = None
        self._log = logging.getLogger(__name__)

    @property
    def request_is_successful(self):
        """Returns value whether the recent HTTP request is successful.
        :rtype:  Boolean
        """
        return self._response.status_code is requests.codes.OK

    @property
    def token_validation_failed(self):
        """Returns value whether the recent HTTP request has token validation error.
        :rtype:  Boolean
        """
        return 'Token validation failed' in self._response.text

    @property
    def not_implemented_error(self):
        """Returns value whether an operation is not implemented in environment.
        :rtype:  Boolean
        """
        return self._response.status_code == requests.codes.not_implemented

    def send_http_request(self, command):
        """Sends HTTP request through SSH.

        :param string command:    command to be done
        :return response:         result of request
        """
        command_url = self._trs_url.format(CGI_DICT[command])
        self._create_login_cookies_for_services_page()
        self._execute_request(requests.get, command_url, cookies=self._cookies)
        if not self.request_is_successful:
            err = "Received unexpected status code ({}) with output\n{}"
            raise CannotEnableServices(err.format(self._response.status_code, self._response.text))

    def send_http_request_with_additional_parameters(self, command):
        """Sends HTTP request through SSH, containing additional tokens as parameters.

        :param command:    command to be done
        """
        service = 'sshservice' if 'ssh' in command else 'RndPortsService'
        html_document = self._parse_html_from_url(service)
        token_params = _create_html_string_with_hidden_items(html_document)
        command_url = self._trs_url.format(CGI_DICT[command] + token_params)
        self._execute_request(requests.get, command_url, cookies=self._cookies)

    def teardown_session(self):
        """Logs out session and close SSH connection."""
        if self._cookies:
            logout_url = self._trs_url.format(CGI_DICT['logout'])
            self._execute_request(requests.post, logout_url, cookies=self._cookies)
            self._cookies = None

    def _create_login_cookies_for_services_page(self):
        payload = {"EncodedCreds": _encode_credentials(self._trs_user, self._trs_pass)}
        login_url = self._trs_url.format(CGI_DICT['login'])
        self._execute_request(requests.post, login_url, data=payload)
        if self.not_implemented_error:
            self._log.debug('login.cgi is not implemented. Login cookies for services page not created')
        self._cookies = self._response.cookies if self._response.cookies.items else None

    def _parse_html_from_url(self, service):
        service_url = self._trs_url.format('{}.html'.format(service))
        self._execute_request(requests.get, service_url, cookies=self._cookies)
        return html.fromstring(self._response.text)

    def _execute_request(self, http_method, url, **kwargs):
        parameters = {"auth": (self._trs_user, self._trs_pass),
                      "verify": False,
                      "timeout": self._timeout}
        parameters.update(**kwargs)
        self._response = http_method(url, **parameters)


class RemoteRequestForwarder(object):
    """Class stores methods needed to get or post requests to remote host via SSH.
    """
    CURL_TEMPLATE = "curl -X '{}' -H 'Accept: */*' -H 'Accept-Encoding: gzip, deflate' -H 'Connection: keep-alive' {}"
    POST_TEMPLATE = CURL_TEMPLATE.format('POST', "-H 'Content-Length: {content_length}' -H 'Content-Type: application/x-www-form-urlencoded' "
                                                 "--max-time {timeout} -d 'EncodedCreds={credentials}' --noproxy '*' -k --cookie-jar - "
                                                 "-u {username}:{password} '{url}'")
    GET_TEMPLATE = CURL_TEMPLATE.format('GET', "--cookie {cookie} --max-time {timeout} -u {username}:{password} --noproxy '*' -k '{url}'")
    BASE_CONTENT_LENGTH = 13

    def __init__(self, ssh_client, remote_ssh_user, remote_ssh_pass, trs_ip, trs_user, trs_pass, timeout):
        """
        :param ssh_client:              SSHLibrary instance with established connection.
        :param remote_ssh_user:         user for remote host
        :param remote_ssh_pass:         password for remote host
        :param string trs_ip:           Transport ip address
        :param string trs_user:         Transport username.
        :param string trs_pass:         Transport password.
        """
        self._ssh_client = ssh_client
        self._remote_ssh_user = remote_ssh_user
        self._remote_ssh_pass = remote_ssh_pass
        self._trs_ip = trs_ip
        self._trs_user = trs_user
        self._trs_pass = trs_pass
        self._timeout = timeout
        self._trs_url = TRS_URL_TEMPLATE.format(trs_ip)
        self._cookies = None
        self._response = None
        self._log = logging.getLogger(__name__)

    @property
    def request_is_successful(self):
        """Returns value whether the recent HTTP request is successful.
        :rtype:  Boolean
        """
        return 'Successfully' in self._response

    @property
    def token_validation_failed(self):
        """Returns value whether the recent HTTP request has token validation error.
        :rtype:  Boolean
        """
        return 'Token validation failed' in self._response

    @property
    def not_implemented_error(self):
        """Returns value whether an operation is not implemented in environment.
        :rtype:  Boolean
        """
        return '501 Not Implemented' in self._response

    @property
    def last_successful_login_is_displayed(self):
        """Returns value whether string indicates successful login.
        :rtype:  Boolean
        """
        return 'Your last successful login' in self._response

    def send_http_request(self, command):
        """Sends HTTP request through SSH.

        :param string command:    command to be executed
        """
        command_url = self._trs_url.format(CGI_DICT[command])
        self._create_login_cookies_for_services_page()
        self._execute_request(self.GET_TEMPLATE, command_url, cookie=self._cookies)
        self._log.debug(self._response)
        if not self.token_validation_failed and not self.request_is_successful:
            raise CannotEnableServices('BTS Procedure not successful due to\n{}'.format(self._response))

    def send_http_request_with_additional_parameters(self, command):
        """Sends HTTP request through SSH, containing additional tokens as parameters.

        :param string command:   Command to be executed
        """
        service = 'sshservice' if 'ssh' in command else 'RndPortsService'
        command_url = self._trs_url.format(CGI_DICT[command])
        html_document = self._parse_html_from_url(service)
        token_params = _create_html_string_with_hidden_items(html_document)
        self._execute_request(self.GET_TEMPLATE, command_url + token_params, cookie=self._cookies)

    def teardown_session(self):
        """Logs out session and close SSH connection."""
        logout_url = self._trs_url.format(CGI_DICT['logout'])
        self._execute_request(self.GET_TEMPLATE, logout_url, cookie=self._cookies)
        self._ssh_client.close()
        self._cookies = None

    def _create_login_cookies_for_services_page(self):
        login_url = self._trs_url.format(CGI_DICT['login'])
        credentials = _encode_credentials(self._trs_user, self._trs_pass)
        content_length = self.BASE_CONTENT_LENGTH + len(credentials)
        self._login_to_remote_host()
        self._execute_request(self.POST_TEMPLATE, login_url, credentials=credentials, content_length=content_length)
        if self.not_implemented_error:
            self._log.debug('login.cgi is not implemented. Login cookies for services page not created')
        self._cookies = '='.join(self._response.split()[-2:]) if self.last_successful_login_is_displayed else None

    def _login_to_remote_host(self):
        if ('look_for_keys' in six.get_function_code(self._ssh_client.login).co_varnames):
            self._ssh_client.login(self._remote_ssh_user, self._remote_ssh_pass, look_for_keys=True)
        else:
            self._ssh_client.login(self._remote_ssh_user, self._remote_ssh_pass)

    def _parse_html_from_url(self, service):
        service_url = self._trs_url.format('{}.html'.format(service))
        self._execute_request(self.GET_TEMPLATE, service_url, cookie=self._cookies)
        return html.fromstring(self._response)

    def _execute_request(self, template, url, **kwargs):
        parameters = {"url": url,
                      "username": self._trs_user,
                      "password": self._trs_pass,
                      "timeout": self._timeout}
        parameters.update(**kwargs)
        self._response = self._ssh_client.execute_command(template.format(**parameters))[0]
